#!/usr/bin/env node
// Writes src/native/expo-module-table-<sdk>.mjs, one per Expo SDK: the Expo native
// modules' members as that SDK's jest-expo declares them, for the native engine to
// answer with (native/expo-module-mocks.mjs), and the index of them,
// src/native/expo-module-tables.mjs.
//
// jest-expo ships a table, generated by Expo from the native modules themselves, of each
// module's constants with their types (`deviceYearClass: number, 2026`) and its
// methods (src/preset/moduleMocks/expoModules.js, with internalExpoModules.js and
// thirdPartyModules.js merged over it in src/preset/setup.js). It is Expo's own data and
// the values a jest-expo suite was written against; a project leaving Jest does not have
// jest-expo installed, so the table is extracted here from a published version. jest-expo's
// major is the SDK's, and each SDK's modules differ (SDK 57's ExpoUpdates has a
// `manifest` constant SDK 58's lacks), so each SDK has its own table.
//
//   node scripts/sync-expo-module-table.mjs [--version <jest-expo version or range>]
//                                           [--package-dir <installed jest-expo>]
//   node scripts/sync-expo-module-table.mjs --check
//
// Without --version or --package-dir, every committed SDK's table is regenerated from the
// newest jest-expo of that major. --package-dir reads an installed jest-expo instead of
// fetching one with `npm pack`.
//
// --check fails when a committed table differs from the newest jest-expo of its major, or
// when npm's newest jest-expo is of an SDK with no table, so a new SDK's table, and a
// change to one, is adopted deliberately.
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const nativeDir = path.join(packageRoot, "src", "native");
const TABLE_FILE = /^expo-module-table-(\d+)\.mjs$/;
const tableFile = (sdk) => path.join(nativeDir, `expo-module-table-${sdk}.mjs`);
const indexFile = path.join(nativeDir, "expo-module-tables.mjs");

// The table is jest-expo's data, so each file carries jest-expo's licence notice.
const header = (version, license) =>
  [
    `// Generated by scripts/sync-expo-module-table.mjs from jest-expo@${version}'s module mocks. Do not edit.`,
    "//",
    "// The data below is extracted from jest-expo, distributed under this licence:",
    "//",
    ...license
      .trim()
      .split("\n")
      .map((line) => (line ? `// ${line}` : "//")),
    "",
  ].join("\n");

const args = process.argv.slice(2);
const check = args.includes("--check");
const option = (name) => {
  const index = args.indexOf(name);
  return index >= 0 ? args[index + 1] : undefined;
};
const requested = option("--version");
const packageDir = option("--package-dir");

const committedSdks = () =>
  fs
    .readdirSync(nativeDir)
    .map((file) => TABLE_FILE.exec(file)?.[1])
    .filter(Boolean)
    .map(Number)
    .sort((a, b) => a - b);

const work = fs.mkdtempSync(path.join(os.tmpdir(), "vitest-native-jest-expo-"));
try {
  if (check) {
    let failed = false;
    for (const sdk of committedSdks()) {
      const { version, modules } = extract(fetchJestExpo(`^${sdk}.0.0`));
      const table = (await import(`${pathToFileURL(tableFile(sdk)).href}?check=${Date.now()}`))
        .default;
      const same = JSON.stringify(table.modules) === JSON.stringify(modules);
      console.log(
        same
          ? `expo-module-table-${sdk}.mjs matches jest-expo@${version}.`
          : `expo-module-table-${sdk}.mjs differs from jest-expo@${version}: run \`node scripts/sync-expo-module-table.mjs --version ${version}\` and review the change.`,
      );
      failed ||= !same;
    }
    const latest = execFileSync("npm", ["view", "jest-expo@latest", "version"], {
      encoding: "utf8",
    }).trim();
    const latestSdk = Number(latest.split(".")[0]);
    if (!committedSdks().includes(latestSdk)) {
      console.log(
        `jest-expo@${latest} is SDK ${latestSdk}, which has no table: run \`node scripts/sync-expo-module-table.mjs --version ${latest}\` and review it.`,
      );
      failed = true;
    }
    process.exitCode = failed ? 1 : 0;
  } else {
    const sources = packageDir
      ? [path.resolve(packageDir)]
      : requested
        ? [fetchJestExpo(requested)]
        : committedSdks().map((sdk) => fetchJestExpo(`^${sdk}.0.0`));
    for (const pkg of sources) {
      const { version, sdk, license, modules } = extract(pkg);
      const table = { source: `jest-expo@${version}`, sdk, license: "MIT", modules };
      // A module, so the build ships it as the native runtime's other files are shipped.
      fs.writeFileSync(
        tableFile(sdk),
        `${header(version, license)}export default ${JSON.stringify(table, null, 1)};\n`,
      );
      console.log(`wrote ${path.relative(packageRoot, tableFile(sdk))} from jest-expo@${version}`);
    }
    writeIndex();
    // In the repository's format, so the committed files are what this writes.
    execFileSync(
      "npx",
      ["--no-install", "oxfmt", indexFile, ...committedSdks().map((sdk) => tableFile(sdk))],
      { cwd: packageRoot, stdio: "ignore" },
    );
  }
} finally {
  fs.rmSync(work, { recursive: true, force: true });
}

// The jest-expo `spec` resolves to on npm (a version, or the newest in a range), unpacked
// into the work directory. Its files are read as data, never installed.
function fetchJestExpo(spec) {
  const into = fs.mkdtempSync(path.join(work, "pack-"));
  const tarball = execFileSync(
    "npm",
    ["pack", `jest-expo@${spec}`, "--silent", "--pack-destination", into],
    { encoding: "utf8" },
  )
    .trim()
    .split("\n")
    .pop();
  execFileSync("tar", ["xzf", path.join(into, tarball), "-C", into]);
  return path.join(into, "package");
}

function extract(pkg) {
  const version = JSON.parse(fs.readFileSync(path.join(pkg, "package.json"), "utf8")).version;
  const req = createRequire(path.join(pkg, "package.json"));
  const mocks = path.join(pkg, "src", "preset", "moduleMocks");
  // jest-expo: merge(publicExpoModules, merge(thirdPartyModules, internalExpoModules)).
  const merged = merge(
    req(path.join(mocks, "expoModules.js")),
    merge(
      req(path.join(mocks, "thirdPartyModules.js")),
      req(path.join(mocks, "internalExpoModules.js")),
    ),
  );
  const proxy = merged.NativeUnimoduleProxy;
  const constants = proxy?.modulesConstants?.mockDefinition ?? {};
  const methods = proxy?.exportedMethods?.mock ?? {};
  const modules = {};
  for (const name of [...new Set([...Object.keys(constants), ...Object.keys(methods)])].sort()) {
    const members = {};
    for (const [member, property] of Object.entries(constants[name] ?? {})) {
      // EventEmitter's own methods come from the runtime's NativeModule.
      if (member === "addListener" || member === "removeListeners") continue;
      members[member] = property;
    }
    for (const { name: method } of methods[name] ?? []) {
      members[method] ??= { type: "function", functionType: "promise" };
      if (members[method].type === "function") members[method].functionType = "promise";
    }
    modules[name] = sortKeys(members);
  }
  return {
    version,
    sdk: Number(version.split(".")[0]),
    license: fs.readFileSync(path.join(pkg, "LICENSE"), "utf8"),
    modules,
  };
}

// The index of every SDK's table, keyed by SDK major.
function writeIndex() {
  const sdks = committedSdks();
  const lines = [
    "// Generated by scripts/sync-expo-module-table.mjs. Do not edit.",
    "// Expo's table of the native modules for each SDK, keyed by SDK major.",
    ...sdks.map((sdk) => `import sdk${sdk} from "./expo-module-table-${sdk}.mjs";`),
    "",
    `export default { ${sdks.map((sdk) => `${sdk}: sdk${sdk}`).join(", ")} };`,
    "",
  ];
  fs.writeFileSync(indexFile, lines.join("\n"));
}

// lodash.merge's semantics for this data, as jest-expo merges it: plain objects merge
// recursively, arrays merge index by index, and anything else is taken from the source.
function merge(target, source) {
  if (Array.isArray(target) && Array.isArray(source)) {
    const out = [...target];
    source.forEach((value, index) => {
      out[index] = mergeValue(out[index], value);
    });
    return out;
  }
  const out = { ...target };
  for (const [key, value] of Object.entries(source)) out[key] = mergeValue(out[key], value);
  return out;
}

function mergeValue(existing, value) {
  const bothObjects = isPlainObject(existing) && isPlainObject(value);
  const bothArrays = Array.isArray(existing) && Array.isArray(value);
  return bothObjects || bothArrays ? merge(existing, value) : value;
}

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function sortKeys(object) {
  return Object.fromEntries(Object.entries(object).sort(([a], [b]) => a.localeCompare(b)));
}
